 * Cycle detection and the unlimited-worker schedule (waves / explain) over
 * the build graph.
 */

import { topoOrder } from './topo.js'

function sortedDeps(deps, name) {
  return [...deps.get(name)].sort()
}

/**
 * Depth-first search from every task in ascending name order, walking each
 * task's dependencies in ascending name order, looking for the first cycle
 * re-entered. Returns the cycle as an array of names (first name repeated at
 * the end), or null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const color = new Map() // undefined = white, 1 = gray, 2 = black
  const names = [...tasks.keys()].sort()

  for (const start of names) {
    if (color.get(start)) continue

    color.set(start, 1)
    const stack = [{ name: start, list: sortedDeps(deps, start), idx: 0 }]

    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      if (frame.idx < frame.list.length) {
        const next = frame.list[frame.idx++]
        const c = color.get(next)
        if (c === undefined) {
          color.set(next, 1)
          stack.push({ name: next, list: sortedDeps(deps, next), idx: 0 })
        } else if (c === 1) {
          const idx = stack.findIndex((f) => f.name === next)
          const cycle = stack.slice(idx).map((f) => f.name)
          cycle.push(next)
          return cycle
        }
      } else {
        color.set(frame.name, 2)
        stack.pop()
      }
    }
  }

  return null
}

/**
 * Compute each task's wave (depth), start and finish time on an unlimited
 * number of workers. Assumes the graph is acyclic.
 */
export function computeSchedule(tasks, deps) {
  const { order } = topoOrder(tasks, deps)

  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  for (const name of order) {
    const depSet = deps.get(name)
    let maxDepth = -1
    let maxFinish = 0
    for (const d of depSet) {
      if (depth.get(d) > maxDepth) maxDepth = depth.get(d)
      if (finish.get(d) > maxFinish) maxFinish = finish.get(d)
    }
    const d0 = depSet.size === 0 ? 0 : maxDepth + 1
    const s = depSet.size === 0 ? 0 : maxFinish
    const f = s + tasks.get(name)
    depth.set(name, d0)
    start.set(name, s)
    finish.set(name, f)
  }

  return { depth, start, finish }
}
"}

