 * Simulation of the build graph on a fixed number of workers.
 */

import { topoOrder } from './topo.js'

/**
 * The priority of a task is the cost of the longest chain that begins at it
 * and follows dependents down to a task nothing depends on.
 */
function computePriority(tasks, order, dependents) {
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let maxChild = 0
    for (const child of dependents.get(name)) {
      const p = priority.get(child)
      if (p > maxChild) maxChild = p
    }
    priority.set(name, tasks.get(name) + maxChild)
  }
  return priority
}

export function pack(tasks, deps, workers) {
  const { order, dependents } = topoOrder(tasks, deps)
  const priority = computePriority(tasks, order, dependents)

  const remaining = new Set(tasks.keys())
  const finishTime = new Map()
  const nextFree = new Array(workers).fill(0)
  const schedule = Array.from({ length: workers }, () => [])
  let currentTime = 0

  function isReady(name) {
    for (const d of deps.get(name)) {
      const f = finishTime.get(d)
      if (f === undefined || f > currentTime) return false
    }
    return true
  }

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < workers; i++) {
        if (nextFree[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of remaining) {
        if (!isReady(name)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const s = currentTime
      const f = s + tasks.get(best)
      schedule[freeWorker].push({ name: best, start: s, finish: f })
      nextFree[freeWorker] = f
      finishTime.set(best, f)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workers; i++) {
      if (nextFree[i] > currentTime && nextFree[i] < next) next = nextFree[i]
    }
    if (!Number.isFinite(next)) break
    currentTime = next
  }

  let makespan = 0
  for (const f of finishTime.values()) if (f > makespan) makespan = f

  return { schedule, makespan }
}
"}

