 * Parsing of the build graph description read from standard input.
 */

export class CliError extends Error {
  constructor(message, exitCode) {
    super(message)
    this.exitCode = exitCode
  }
}

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

/**
 * Parse the textual build graph description into a map of task costs and a
 * map of task dependency sets. Throws CliError on any malformed input.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set<name>
  const depLines = [] // { name, depNames, lineNo }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      const name = words[1]
      const depNames = words.slice(2)
      depLines.push({ name, depNames, lineNo })
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const { name, depNames } of depLines) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`, 2)
    }
    for (const d of depNames) {
      if (!tasks.has(d)) {
        throw new CliError(`error: unknown task ${d}`, 2)
      }
    }
  }

  for (const { name, depNames } of depLines) {
    const set = deps.get(name)
    for (const d of depNames) set.add(d)
  }

  return { tasks, deps }
}
"}

