 * Topological ordering of the build graph, shared by the wave/explain and
 * pack computations. Assumes the graph is already known to be acyclic.
 */

export function topoOrder(tasks, deps) {
  const indegree = new Map()
  const dependents = new Map()
  for (const name of tasks.keys()) {
    indegree.set(name, 0)
    dependents.set(name, [])
  }
  for (const [name, depSet] of deps) {
    indegree.set(name, depSet.size)
    for (const d of depSet) {
      dependents.get(d).push(name)
    }
  }
  for (const list of dependents.values()) list.sort()

  const order = [...tasks.keys()].filter((n) => indegree.get(n) === 0).sort()
  let head = 0
  while (head < order.length) {
    const name = order[head++]
    for (const child of dependents.get(name)) {
      const next = indegree.get(child) - 1
      indegree.set(child, next)
      if (next === 0) order.push(child)
    }
  }

  return { order, dependents }
}
